import { readFile,writeFile } from 'node:fs/promises'; import {join} from 'node:path';import {cloneCard} from '../../vendor/discstudio/disc/export-ui.ts';import {renderCard} from '../../vendor/discstudio/disc/card-renderer.ts';
export async function calculate({inputs,outputDir,viewArgs}){const saved=JSON.parse(await readFile(inputs['parts/saved/discstudio'].files[0],'utf8'));if(saved.basePainter!=='OFF'||!saved.inputIdentities?.original||!saved.inputIdentities?.crop||!saved.inputIdentities?.prepared||!saved.row?.disc?.photo)throw Error('Retained photo-first native save required.');const card=cloneCard(saved.row,viewArgs.orientation,viewArgs.preset),png=await renderCard(card.disc,card.orientation,card.cardDesign),image=join(outputDir,'card.png'),receipt=join(outputDir,'card.json');await writeFile(image,png);await writeFile(receipt,JSON.stringify({schema:'discstudio-nctk-card@1',sourceDiscAddress:saved.discAddress,inputIdentities:saved.inputIdentities,basePainter:'OFF',orientation:card.orientation,preset:card.cardDesign,renderer:'DiscStudio card-renderer.ts',bytes:png.length},null,2)+'\n');return {files:[image,receipt],observation:{renderer:'native DiscStudio card-renderer.ts',basePainter:'OFF',orientation:card.orientation,preset:card.cardDesign,bytes:png.length}};}
